// Code node "Build mood message" (mode: Run Once for All Items).
// Combines the Fear & Greed index (alternative.me) and CoinGecko prices into one daily message.

// Telegram is sent with parse mode HTML: neutralise the only three special characters.
const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const cfg = $('Settings').first().json;
const currency = String(cfg.currency || 'usd').trim().toLowerCase();
const coins = String(cfg.coins || '')
  .split(',')
  .map((s) => s.trim().toLowerCase())
  .filter(Boolean);
if (coins.length === 0) throw new Error('Settings: add at least one CoinGecko coin id in "coins" (e.g. bitcoin, ethereum).');

// Fear & Greed: data[0] = today, data[1] = yesterday, data[7] = a week ago.
const fng = $('Fetch Fear & Greed index').first().json;
const days = Array.isArray(fng.data) ? fng.data : [];
if (!days.length) throw new Error(`Fear & Greed API returned no data: ${JSON.stringify(fng).slice(0, 200)}`);
const value = (d) => (d ? Number(d.value) : NaN);
const today = days[0];
const trend = (past, label) => {
  const v = value(past);
  if (!Number.isFinite(v)) return null;
  const diff = value(today) - v;
  return diff === 0 ? `same as ${label} (${v})` : `${diff > 0 ? '▲' : '▼'} from ${v} ${label}`;
};
const trends = [trend(days[1], 'yesterday'), trend(days[7], 'a week ago')].filter(Boolean);

// Mini chart of the last 8 days (oldest on the left), scale 0-100.
const BARS = '▁▂▃▄▅▆▇█';
const spark = days.slice(0, 8).reverse().map(value).filter(Number.isFinite)
  .map((v) => BARS[Math.max(0, Math.min(7, Math.floor(v / 12.5)))]).join('');

// Alert rules: extreme readings or a big jump since yesterday.
const num = (v, fallback) => (String(v ?? '').trim() !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback);
const fearBelow = num(cfg.fear_below, 25);
const greedAbove = num(cfg.greed_above, 75);
const jumpPoints = num(cfg.jump_points, 10);
if (fearBelow >= greedAbove) throw new Error('Settings: "fear_below" must be lower than "greed_above" (for example 25 and 75).');
const onlyExtremes = cfg.only_extremes === true || String(cfg.only_extremes).toLowerCase() === 'true';
const now = value(today);
const reasons = [];
if (now <= fearBelow) reasons.push(`⚡ Extreme fear: ${now} is at or below your threshold (${fearBelow})`);
if (now >= greedAbove) reasons.push(`⚡ Extreme greed: ${now} is at or above your threshold (${greedAbove})`);
const yesterday = value(days[1]);
if (Number.isFinite(yesterday) && Math.abs(now - yesterday) >= jumpPoints) {
  reasons.push(`⚡ Big move: ${now - yesterday > 0 ? '+' : ''}${now - yesterday} points since yesterday`);
}
// "Only extremes" mode: stay silent on ordinary days (no message at all).
if (onlyExtremes && reasons.length === 0) return [];

// Prices
const prices = $('Fetch coin prices').first().json;
if (!prices || typeof prices !== 'object' || prices.status) {
  throw new Error(`CoinGecko did not return prices: ${JSON.stringify(prices).slice(0, 200)}`);
}
let format;
try {
  format = (n) => new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency.toUpperCase(),
    ...(n < 1 ? { maximumSignificantDigits: 4 } : { maximumFractionDigits: n < 100 ? 2 : 0 }),
  }).format(n);
  format(1);
} catch (e) {
  throw new Error(`Settings: "${currency}" is not a valid currency code (e.g. usd, eur).`);
}
const name = (id) => id.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());

const lines = [];
const unknown = [];
for (const id of coins) {
  const p = prices[id];
  const price = p && Number(p[currency]);
  if (!Number.isFinite(price)) {
    unknown.push(id);
    continue;
  }
  const change = Number(p[`${currency}_24h_change`]);
  const changeText = Number.isFinite(change) ? ` (${change >= 0 ? '+' : ''}${change.toFixed(2)}% 24h)` : '';
  lines.push(`${name(id)}: ${format(price)}${changeText}`);
}

const date = new Date().toISOString().slice(0, 10);
const message = [
  `🧭 Crypto market mood · ${date}`,
  '',
  `Fear & Greed: ${value(today)} · ${today.value_classification}`,
  trends.length ? trends.join(' · ') : null,
  spark.length > 1 ? `Last ${spark.length} days: ${spark}` : null,
  ...reasons,
  '',
  ...lines,
  unknown.length ? `\n⚠️ Unknown coin id(s): ${unknown.join(', ')} (use CoinGecko ids, e.g. "bitcoin", not "BTC")` : null,
].filter((l) => l !== null).join('\n');

return [{ json: { message: escapeHtml(message), fear_greed: value(today), classification: today.value_classification, alert: reasons.length > 0 } }];
